class MainActivity : AppCompatActivity() {

    private var cameraSource: CameraSource? = null

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        window.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)


        setContent {
            MaterialTheme {
                PoseEstimationScreen()
            }
        }
    }

    @OptIn(ExperimentalMaterial3Api::class)
    @Composable
    fun PoseEstimationScreen() {
        val context = LocalContext.current
        val lifecycleOwner = LocalLifecycleOwner.current

        var personScore by remember { mutableStateOf(0f) }
        var fps by remember { mutableStateOf(0) }
        var poseLabels by remember { mutableStateOf<List<Pair<String, Float>>>(emptyList()) }

        var modelPos by remember { mutableIntStateOf(1) } // Default: MoveNet Thunder
        var device by remember { mutableStateOf(Device.CPU) }
        var trackerPos by remember { mutableIntStateOf(0) } // Default: Off
        var isClassifyPose by remember { mutableStateOf(false) }

        var showScore by remember { mutableStateOf(true) }
        var showTracker by remember { mutableStateOf(false) }
        var showClassifierOption by remember { mutableStateOf(true) }

        var hasCameraPermission by remember {
            mutableStateOf(ContextCompat.checkSelfPermission(context, Manifest.permission.CAMERA) == PackageManager.PERMISSION_GRANTED)
        }

        var resumeCount by remember { mutableIntStateOf(0) }

        // Handle Lifecycle
        DisposableEffect(lifecycleOwner) {
            val observer = LifecycleEventObserver { _, event ->
                when (event) {
                    Lifecycle.Event.ON_RESUME -> {
                        cameraSource?.resume()
                        resumeCount++
                    }
                    Lifecycle.Event.ON_PAUSE -> {
                        cameraSource?.close()
                        cameraSource = null
                    }
                    else -> {}
                }
            }
            lifecycleOwner.lifecycle.addObserver(observer)
            onDispose {
                lifecycleOwner.lifecycle.removeObserver(observer)
                cameraSource?.close()
                cameraSource = null
            }
        }

        val requestPermissionLauncher = rememberLauncherForActivityResult(
            ActivityResultContracts.RequestPermission()
        ) { isGranted: Boolean ->
            hasCameraPermission = isGranted
            if (!isGranted) {
                Toast.makeText(context, R.string.tfe_pe_request_permission, Toast.LENGTH_LONG).show()
            }
        }

        LaunchedEffect(Unit) {
            if (!hasCameraPermission) {
                requestPermissionLauncher.launch(Manifest.permission.CAMERA)
            }
        }

        // Handle model/device/tracker changes
        LaunchedEffect(modelPos, device) {
            createPoseEstimator(modelPos, device,
                onShowScore = { showScore = it },
                onShowTracker = { showTracker = it },
                onShowClassifier = { showClassifierOption = it }
            )
        }

        LaunchedEffect(trackerPos) {
            cameraSource?.setTracker(
                when (trackerPos) {
                    1 -> TrackerType.BOUNDING_BOX
                    2 -> TrackerType.KEYPOINTS
                    else -> TrackerType.OFF
                }
            )
        }

        LaunchedEffect(isClassifyPose) {
            cameraSource?.setClassifier(if (isClassifyPose) PoseClassifier.create(context) else null)
        }

        val scaffoldState = rememberBottomSheetScaffoldState()

        BottomSheetScaffold(
            scaffoldState = scaffoldState,
            sheetPeekHeight = 80.dp,
            sheetContainerColor = Color.White,
            sheetContentColor = Color.Black,
            sheetContent = {
                ControlPanel(
                    fps = fps,
                    score = personScore,
                    modelPos = modelPos,
                    device = device,
                    trackerPos = trackerPos,
                    isClassifyPose = isClassifyPose,
                    poseLabels = poseLabels,
                    showScore = showScore,
                    showTracker = showTracker,
                    showClassifierOption = showClassifierOption,
                    onModelChange = { modelPos = it },
                    onDeviceChange = { device = it },
                    onTrackerChange = { trackerPos = it },
                    onClassificationChange = { isClassifyPose = it }
                )
            }
        ) { padding ->
            Box(modifier = Modifier.padding(padding)) {
                if (hasCameraPermission) {
                    AndroidView(
                        factory = { ctx ->
                            SurfaceView(ctx)
                        },
                        modifier = Modifier.fillMaxSize(),
                        update = { sv ->
                            if (cameraSource == null) {
                                openCamera(
                                    sv,
                                    onFPS = { fps = it },
                                    onDetected = { score, labels ->
                                        personScore = score ?: 0f
                                        poseLabels = labels ?: emptyList()
                                    }
                                )
                                createPoseEstimator(modelPos, device,
                                    onShowScore = { showScore = it },
                                    onShowTracker = { showTracker = it },
                                    onShowClassifier = { showClassifierOption = it }
                                )
                                // If classification was already on, we need to set it
                                if (isClassifyPose) {
                                    cameraSource?.setClassifier(PoseClassifier.create(context))
                                }
                                // If tracker was already on, we need to set it
                                cameraSource?.setTracker(
                                    when (trackerPos) {
                                        1 -> TrackerType.BOUNDING_BOX
                                        2 -> TrackerType.KEYPOINTS
                                        else -> TrackerType.OFF
                                    }
                                )
                            }
                        }
                    )
                }

                // Toolbar
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(56.dp)
                        .background(Color.Black.copy(alpha = 0.4f))
                        .padding(horizontal = 16.dp),
                    contentAlignment = Alignment.CenterStart
                ) {
                    Image(
                        painter = painterResource(id = R.drawable.tfl2_logo),
                        contentDescription = null
                    )
                }
            }
        }
    }

    @OptIn(ExperimentalMaterial3Api::class)
    @Composable
    fun ControlPanel(
        fps: Int,
        score: Float,
        modelPos: Int,
        device: Device,
        trackerPos: Int,
        isClassifyPose: Boolean,
        poseLabels: List<Pair<String, Float>>,
        showScore: Boolean,
        showTracker: Boolean,
        showClassifierOption: Boolean,
        onModelChange: (Int) -> Unit,
        onDeviceChange: (Device) -> Unit,
        onTrackerChange: (Int) -> Unit,
        onClassificationChange: (Boolean) -> Unit
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Icon(
                imageVector = Icons.Default.KeyboardArrowUp,
                contentDescription = null,
                modifier = Modifier.align(Alignment.CenterHorizontally)
            )

            Text(text = stringResource(id = R.string.tfe_pe_tv_fps, fps))
            if (showScore) {
                Text(text = stringResource(id = R.string.tfe_pe_tv_score, score))
            }

            // Device Spinner
            SpinnerRow(
                label = stringResource(id = R.string.tfe_pe_tv_device),
                options = stringArrayResource(id = R.array.tfe_pe_device_name).toList(),
                selectedOption = when (device) {
                    Device.CPU -> 0
                    Device.GPU -> 1
                    Device.NNAPI -> 2
                },
                onOptionSelected = {
                    val targetDevice = when (it) {
                        0 -> Device.CPU
                        1 -> Device.GPU
                        else -> Device.NNAPI
                    }
                    onDeviceChange(targetDevice)
                }
            )

            // Model Spinner
            SpinnerRow(
                label = stringResource(id = R.string.tfe_pe_tv_model),
                options = stringArrayResource(id = R.array.tfe_pe_models_array).toList(),
                selectedOption = modelPos,
                onOptionSelected = onModelChange
            )

            // Tracker Spinner
            if (showTracker) {
                SpinnerRow(
                    label = stringResource(id = R.string.tfe_pe_tv_tracking),
                    options = stringArrayResource(id = R.array.tfe_pe_tracker_array).toList(),
                    selectedOption = trackerPos,
                    onOptionSelected = onTrackerChange
                )
            }

            // Classification Switch
            if (showClassifierOption) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Text(text = stringResource(id = R.string.tfe_pe_tv_pose_classification))
                    Switch(checked = isClassifyPose, onCheckedChange = onClassificationChange)
                }

                if (isClassifyPose) {
                    poseLabels.sortedByDescending { it.second }.take(3).forEach { label ->
                        Text(
                            text = stringResource(
                                id = R.string.tfe_pe_tv_classification_value,
                                "${label.first} (${String.format(Locale.US, "%.2f", label.second)})"
                            )
                        )
                    }
                }
            }
        }
    }

    @OptIn(ExperimentalMaterial3Api::class)
    @Composable
    fun SpinnerRow(
        label: String,
        options: List<String>,
        selectedOption: Int,
        onOptionSelected: (Int) -> Unit
    ) {
        var expanded by remember { mutableStateOf(false) }

        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            Text(text = label)
            Box {
                Text(
                    text = options[selectedOption],
                    modifier = Modifier
                        .clickable { expanded = true }
                        .padding(8.dp)
                )
                DropdownMenu(expanded = expanded, onDismissRequest = { expanded = false }) {
                    options.forEachIndexed { index, option ->
                        DropdownMenuItem(
                            text = { Text(text = option) },
                            onClick = {
                                onOptionSelected(index)
                                expanded = false
                            }
                        )
                    }
                }
            }
        }
    }

    private fun openCamera(
        surfaceView: SurfaceView,
        onFPS: (Int) -> Unit,
        onDetected: (Float?, List<Pair<String, Float>>?) -> Unit
    ) {
        if (cameraSource == null) {
            cameraSource =
                CameraSource(surfaceView, object : CameraSource.CameraSourceListener {
                    override fun onFPSListener(fps: Int) {
                        onFPS(fps)
                    }

                    override fun onDetectedInfo(
                        personScore: Float?,
                        poseLabels: List<Pair<String, Float>>?
                    ) {
                        onDetected(personScore, poseLabels)
                    }

                }).apply {
                    prepareCamera()
                }
            lifecycleScope.launch(Dispatchers.Main) {
                cameraSource?.initCamera()
            }
        }
    }

    private fun createPoseEstimator(
        modelPos: Int,
        device: Device,
        onShowScore: (Boolean) -> Unit,
        onShowTracker: (Boolean) -> Unit,
        onShowClassifier: (Boolean) -> Unit
    ) {
        val poseDetector = when (modelPos) {
            0 -> {
                // MoveNet Lightning (SinglePose)
                onShowClassifier(true)
                onShowScore(true)
                onShowTracker(false)
                MoveNet.create(this, device, ModelType.Lightning)
            }
            1 -> {
                // MoveNet Thunder (SinglePose)
                onShowClassifier(true)
                onShowScore(true)
                onShowTracker(false)
                MoveNet.create(this, device, ModelType.Thunder)
            }
            2 -> {
                // MoveNet (Lightning) MultiPose
                onShowClassifier(false)
                onShowScore(false)
                if (device == Device.GPU) {
                    Toast.makeText(this, getString(R.string.tfe_pe_gpu_error), Toast.LENGTH_LONG).show()
                }
                onShowTracker(true)
                MoveNetMultiPose.create(this, device, Type.Dynamic)
            }
            3 -> {
                // PoseNet (SinglePose)
                onShowClassifier(true)
                onShowScore(true)
                onShowTracker(false)
                PoseNet.create(this, device)
            }
            else -> null
        }
        poseDetector?.let { detector ->
            cameraSource?.setDetector(detector)
        }
    }
}

